export const PYQ = [
// ── CHEMISTRY (60Q) ───────────────────────────────────────────────────────
{id:"c1",y:2006,q:"Which has maximum unpaired electrons?",o:{A:"Mg²⁺",B:"Ti³⁺",C:"V³⁺",D:"Fe²⁺"},a:"D",e:"Fe²⁺: [Ar]3d⁶ → 4 unpaired electrons. V³⁺=2, Ti³⁺=1, Mg²⁺=0.",ch:"d & f Block Elements",sub:"Chemistry",d:"medium"},
{id:"c2",y:2007,q:"SF₆ hybridisation is:",o:{A:"sp³d",B:"sp³d²",C:"sp³",D:"sp²d²"},a:"B",e:"SF₆: 6 bond pairs, 0 lone pairs → sp³d² (octahedral geometry).",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c3",y:2008,q:"Which compound has the highest lattice energy?",o:{A:"NaCl",B:"KCl",C:"MgO",D:"NaF"},a:"C",e:"MgO: Mg²⁺(+2) and O²⁻(−2) — higher charges + smaller radii = highest lattice energy.",ch:"s-Block Elements",sub:"Chemistry",d:"medium"},
{id:"c4",y:2009,q:"BF₃ has zero dipole moment because:",o:{A:"B–F bond is non-polar",B:"Trigonal planar — bond dipoles cancel",C:"B has no lone pairs",D:"F is less electronegative than B"},a:"B",e:"BF₃ is sp² hybridised, trigonal planar. Three equal bond dipoles at 120° cancel → μ = 0.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c5",y:2010,q:"Number of σ bonds in N₂H₄:",o:{A:"4",B:"5",C:"6",D:"3"},a:"B",e:"N–N (1σ) + 4×N–H (4σ) = 5 sigma bonds total.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c6",y:2011,q:"Which is most acidic?",o:{A:"Phenol",B:"p-nitrophenol",C:"p-cresol",D:"Benzyl alcohol"},a:"B",e:"–NO₂ is strong EWG, stabilises phenoxide by –M and –I effects → most acidic.",ch:"Alcohols, Phenols & Ethers",sub:"Chemistry",d:"medium"},
{id:"c7",y:2012,q:"Isoelectronic pair:",o:{A:"Na⁺, Mg²⁺",B:"Na⁺, K⁺",C:"Ca²⁺, K⁺",D:"Cl⁻, K⁺"},a:"A",e:"Na⁺ and Mg²⁺ both have 10 electrons (Ne configuration).",ch:"Structure of Atom",sub:"Chemistry",d:"medium"},
{id:"c8",y:2013,q:"Hybridisation of SF₄:",o:{A:"sp³",B:"sp³d",C:"sp³d²",D:"sp²d"},a:"B",e:"SF₄: 4 bond pairs + 1 lone pair = 5 electron pairs → sp³d (see-saw geometry).",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"medium"},
{id:"c9",y:2014,q:"SN2 reaction preferentially occurs with:",o:{A:"(CH₃)₃CBr + OH⁻",B:"CH₃Br + OH⁻",C:"(CH₃)₂CHBr + H₂O",D:"C₆H₅Br + OH⁻"},a:"B",e:"SN2 favours primary halides — CH₃Br has least steric hindrance. Tertiary goes SN1.",ch:"Haloalkanes & Haloarenes",sub:"Chemistry",d:"medium"},
{id:"c10",y:2015,q:"Unit of rate constant for second order reaction:",o:{A:"mol L⁻¹ s⁻¹",B:"s⁻¹",C:"L mol⁻¹ s⁻¹",D:"mol² L⁻² s⁻¹"},a:"C",e:"For nth order: L^(n-1) mol^(1-n) s⁻¹. For n=2: L mol⁻¹ s⁻¹.",ch:"Chemical Kinetics",sub:"Chemistry",d:"easy"},
{id:"c11",y:2016,q:"Example of linkage isomerism:",o:{A:"[Co(NH₃)₅Cl]²⁺ and [Co(NH₃)₄Cl₂]⁺",B:"[Co(NH₃)₅NO₂]²⁺ and [Co(NH₃)₅ONO]²⁺",C:"cis and trans [Pt(NH₃)₂Cl₂]",D:"d and l [Co(en)₂Cl₂]⁺"},a:"B",e:"Linkage isomers: NO₂⁻ bonds via N (nitro) or O (nitrito) — same formula, different donor atom.",ch:"Coordination Compounds",sub:"Chemistry",d:"medium"},
{id:"c12",y:2017,q:"Maximum number of atoms in 1g:",o:{A:"N₂",B:"P₄",C:"H₂",D:"Al"},a:"C",e:"H₂: 0.5 mol → 1 mol H atoms. Lowest molar mass = most atoms per gram.",ch:"Some Basic Concepts",sub:"Chemistry",d:"medium"},
{id:"c13",y:2018,q:"Geometry of XeF₄:",o:{A:"Tetrahedral",B:"Square planar",C:"See-saw",D:"Trigonal bipyramidal"},a:"B",e:"XeF₄: 4 BP + 2 LP (sp³d²) → square planar molecular geometry.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c14",y:2019,q:"Nitrogen has +5 oxidation state in:",o:{A:"N₂O",B:"NO",C:"HNO₃",D:"NH₄⁺"},a:"C",e:"HNO₃: x + 3(−2) + 1 = 0 → x = +5. N₂O → +1, NO → +2, NH₄⁺ → −3.",ch:"p-Block Elements (Gr 15-18)",sub:"Chemistry",d:"easy"},
{id:"c15",y:2020,q:"Condition for spontaneous process at constant T and P:",o:{A:"ΔG > 0",B:"ΔG = 0",C:"ΔG < 0",D:"ΔS < 0"},a:"C",e:"Gibbs criterion: ΔG < 0 → spontaneous. ΔG = 0 → equilibrium.",ch:"Thermodynamics",sub:"Chemistry",d:"easy"},
{id:"c16",y:2021,q:"Which is NOT a semiconductor?",o:{A:"Ge",B:"Si",C:"Diamond",D:"GaAs"},a:"C",e:"Diamond has band gap ~5.5 eV → insulator, not semiconductor.",ch:"Semiconductor Electronics",sub:"Chemistry",d:"medium"},
{id:"c17",y:2022,q:"Number of σ bonds in allene (CH₂=C=CH₂):",o:{A:"5",B:"6",C:"7",D:"4"},a:"B",e:"4 C–H bonds (σ) + 2 C=C bonds (each 1σ+1π) = 6 sigma bonds.",ch:"Hydrocarbons",sub:"Chemistry",d:"medium"},
{id:"c18",y:2023,q:"Which shows optical isomerism?",o:{A:"[Co(NH₃)₃Cl₃]",B:"[Co(en)₂Cl₂]⁺",C:"[Pt(NH₃)₂Cl₂]",D:"[Ni(CO)₄]"},a:"B",e:"[Co(en)₂Cl₂]⁺ cis form is chiral — Δ and Λ enantiomers.",ch:"Coordination Compounds",sub:"Chemistry",d:"hard"},
{id:"c19",y:2024,q:"Correct boiling point order of Group 16 hydrides:",o:{A:"H₂S<H₂Se<H₂Te<H₂O",B:"H₂O>H₂Te>H₂Se>H₂S",C:"H₂S<H₂Se<H₂O<H₂Te",D:"H₂O<H₂S<H₂Se<H₂Te"},a:"B",e:"H₂O anomalously high bp (H-bonding). Rest ∝ MW: H₂O > H₂Te > H₂Se > H₂S.",ch:"p-Block Elements (Gr 15-18)",sub:"Chemistry",d:"medium"},
{id:"c20",y:2025,q:"Nylon-6 is formed by:",o:{A:"Condensation of hexamethylenediamine + adipic acid",B:"Ring-opening polymerisation of caprolactam",C:"Condensation of glycine",D:"Condensation of ethylene glycol + terephthalic acid"},a:"B",e:"Nylon-6: ring-opening polymerisation of caprolactam. Nylon-6,6 uses option A.",ch:"Polymers",sub:"Chemistry",d:"easy"},
{id:"c21",y:2020,q:"Raoult's law: partial vapour pressure of a volatile component equals:",o:{A:"Inversely proportional to its mole fraction",B:"P° × mole fraction of that component",C:"Same for all components",D:"Independent of mole fraction"},a:"B",e:"Pₐ = Pₐ° × xₐ. Partial pressure = vapour pressure of pure component × mole fraction.",ch:"Solutions",sub:"Chemistry",d:"easy"},
{id:"c22",y:2019,q:"Lyophilic colloid among these:",o:{A:"Gold sol",B:"Starch sol",C:"As₂S₃ sol",D:"Fe(OH)₃ sol"},a:"B",e:"Lyophilic = solvent-loving: starch, gelatin, proteins. Inorganic sols are lyophobic.",ch:"Surface Chemistry",sub:"Chemistry",d:"medium"},
{id:"c23",y:2018,q:"Best reducing agent in electrochemical series:",o:{A:"Cu",B:"Zn",C:"Ag",D:"Au"},a:"B",e:"Lower E° = better reducing agent. Zn(−0.76V) best among these.",ch:"Electrochemistry",sub:"Chemistry",d:"easy"},
{id:"c24",y:2016,q:"Coordination number of Cr in [Cr(en)₂Cl₂]⁺:",o:{A:"4",B:"6",C:"8",D:"3"},a:"B",e:"en is bidentate (2 donor atoms). 2×en = 4, + 2Cl = 6. CN = 6.",ch:"Coordination Compounds",sub:"Chemistry",d:"easy"},
{id:"c25",y:2015,q:"Sandmeyer reaction:",o:{A:"ArNH₂ + HNO₂ → ArN₂⁺",B:"ArN₂⁺ + CuCN → ArCN",C:"ArNO₂ + Sn/HCl → ArNH₂",D:"ArH + HNO₃ → ArNO₂"},a:"B",e:"Sandmeyer: diazonium + CuCN → aryl nitrile. CuCl gives ArCl, CuBr gives ArBr.",ch:"Amines",sub:"Chemistry",d:"medium"},
{id:"c26",y:2017,q:"Rate of 2NO+Cl₂→2NOCl doubles when [Cl₂] is doubled. Order w.r.t. Cl₂:",o:{A:"0",B:"1",C:"2",D:"3"},a:"B",e:"Rate ∝ [Cl₂]ⁿ. 2ⁿ = 2 → n = 1.",ch:"Chemical Kinetics",sub:"Chemistry",d:"easy"},
{id:"c27",y:2019,q:"p-Block element NOT showing +5 oxidation state:",o:{A:"N",B:"P",C:"As",D:"Bi"},a:"A",e:"N has no d-orbitals, cannot expand its octet beyond the normal.",ch:"p-Block Elements (Gr 15-18)",sub:"Chemistry",d:"medium"},
{id:"c28",y:2013,q:"Standard electrode potential of SHE (Standard Hydrogen Electrode):",o:{A:"+1.0 V",B:"−1.0 V",C:"0.00 V",D:"+0.5 V"},a:"C",e:"By convention, SHE = 0.00 V. All other electrode potentials measured against it.",ch:"Electrochemistry",sub:"Chemistry",d:"easy"},
{id:"c29",y:2022,q:"3° alcohol gives turbidity with Lucas reagent:",o:{A:"After several hours",B:"After 5 minutes",C:"Immediately",D:"No reaction at all"},a:"C",e:"3° alcohol + ZnCl₂/HCl → immediate turbidity (forms alkyl chloride).",ch:"Alcohols, Phenols & Ethers",sub:"Chemistry",d:"easy"},
{id:"c30",y:2026,q:"Which molecule has zero dipole moment?",o:{A:"NF₃",B:"CHCl₃",C:"CCl₄",D:"H₂O"},a:"C",e:"CCl₄ is perfectly tetrahedral — all four C–Cl bond dipoles cancel symmetrically → μ = 0.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c31",y:2025,q:"IUPAC name of CH₃–CH(OH)–COOH:",o:{A:"2-hydroxypropanoic acid",B:"3-hydroxypropanoic acid",C:"2-hydroxyethanoic acid",D:"Propan-2-ol-1-oic acid"},a:"A",e:"3C chain (propanoic acid), OH at C2 → 2-hydroxypropanoic acid (lactic acid).",ch:"Basic Principles of Organic",sub:"Chemistry",d:"easy"},
{id:"c32",y:2024,q:"For N₂ + 3H₂ ⇌ 2NH₃, the relation between Kp and Kc:",o:{A:"Kp = Kc(RT)²",B:"Kp = Kc(RT)⁻²",C:"Kp = Kc(RT)",D:"Kp = Kc"},a:"B",e:"Δn = 2 − 4 = −2. Kp = Kc(RT)^Δn = Kc(RT)⁻².",ch:"Equilibrium",sub:"Chemistry",d:"medium"},
{id:"c33",y:2023,q:"Highest covalent character among:",o:{A:"LiCl",B:"NaCl",C:"BeCl₂",D:"MgCl₂"},a:"C",e:"Fajan's rules: Be²⁺ has smallest size + highest charge density → most polarising → most covalent.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"medium"},
{id:"c34",y:2020,q:"NOT a colligative property:",o:{A:"Osmotic pressure",B:"Elevation in boiling point",C:"Optical activity",D:"Depression in freezing point"},a:"C",e:"Colligative properties depend only on number of solute particles. Optical activity depends on structure.",ch:"Solutions",sub:"Chemistry",d:"easy"},
{id:"c35",y:2026,q:"Reagent used in Reimer-Tiemann reaction:",o:{A:"CHCl₃ / KOH",B:"CCl₄ / KOH",C:"CH₃Cl / AlCl₃",D:"HCHO / HCl"},a:"A",e:"Phenol + CHCl₃ + KOH → salicylaldehyde. CHCl₃/KOH generates dichlorocarbene (:CCl₂).",ch:"Alcohols, Phenols & Ethers",sub:"Chemistry",d:"medium"},
{id:"c36",y:2024,q:"IUPAC name of diethyl ether (C₂H₅OC₂H₅):",o:{A:"Ethoxyethane",B:"Diethyl oxide",C:"1-ethoxyethane",D:"Oxydiethane"},a:"A",e:"IUPAC: larger chain = parent (ethane), smaller = alkoxy prefix (ethoxy) → ethoxyethane.",ch:"Alcohols, Phenols & Ethers",sub:"Chemistry",d:"easy"},
{id:"c37",y:2023,q:"Which polymer is formed by addition polymerisation?",o:{A:"Nylon-6,6",B:"Polyethylene",C:"Bakelite",D:"Dacron (PET)"},a:"B",e:"Polyethylene: addition polymerisation of ethylene (no byproduct). Others are condensation polymers.",ch:"Polymers",sub:"Chemistry",d:"easy"},
{id:"c38",y:2022,q:"Catalyst used in Haber's process for NH₃:",o:{A:"Pt",B:"Fe with Mo promoter",C:"V₂O₅",D:"Ni"},a:"B",e:"Haber process: Fe catalyst + Mo promoter. Pt is for Ostwald's; V₂O₅ for Contact process.",ch:"Equilibrium",sub:"Chemistry",d:"easy"},
{id:"c39",y:2021,q:"pH of 0.001 M HCl solution:",o:{A:"3",B:"11",C:"1",D:"2"},a:"A",e:"HCl is a strong acid: [H⁺] = 10⁻³ M → pH = −log(10⁻³) = 3.",ch:"Equilibrium",sub:"Chemistry",d:"easy"},
{id:"c40",y:2020,q:"Compound with maximum bond angle:",o:{A:"NH₃",B:"H₂O",C:"CH₄",D:"NF₃"},a:"C",e:"CH₄: 109.5° > NH₃: 107° > H₂O: 104.5° > NF₃: 102.5°. More lone pairs → smaller angle.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"easy"},
{id:"c41",y:2019,q:"Glucose is classified as:",o:{A:"Disaccharide",B:"Polysaccharide",C:"Hexose monosaccharide",D:"Pentose monosaccharide"},a:"C",e:"Glucose: simplest carbohydrate, cannot be hydrolysed, has 6 carbons → hexose monosaccharide.",ch:"Biomolecules",sub:"Chemistry",d:"easy"},
{id:"c42",y:2018,q:"Drug that is both analgesic AND antipyretic:",o:{A:"Penicillin",B:"Aspirin",C:"Chloroquine",D:"Streptomycin"},a:"B",e:"Aspirin (acetylsalicylic acid) = analgesic (pain relief) + antipyretic (reduces fever).",ch:"Chemistry in Everyday Life",sub:"Chemistry",d:"easy"},
{id:"c43",y:2017,q:"1 Faraday is the charge carried by:",o:{A:"1 mole of electrons",B:"2 moles of electrons",C:"Avogadro's number of protons",D:"0.5 moles of electrons"},a:"A",e:"1 Faraday = 96500 C = charge of 1 mole of electrons (Avogadro's number × electron charge).",ch:"Electrochemistry",sub:"Chemistry",d:"medium"},
{id:"c44",y:2016,q:"INCORRECT hybridisation matching:",o:{A:"BeCl₂ — sp",B:"BCl₃ — sp²",C:"NF₃ — sp³",D:"SF₆ — sp³d"},a:"D",e:"SF₆ has 6 bond pairs → sp³d², NOT sp³d. The rest are all correct.",ch:"Chemical Bonding & Molecular Structure",sub:"Chemistry",d:"hard"},
{id:"c45",y:2015,q:"Catalyst in Contact process for H₂SO₄ production:",o:{A:"Fe",B:"Pt",C:"V₂O₅",D:"MnO₂"},a:"C",e:"Contact process: SO₂ → SO₃ uses V₂O₅ (vanadium pentoxide). Pt used in Ostwald's process.",ch:"p-Block Elements (Gr 15-18)",sub:"Chemistry",d:"easy"},
{id:"c46",y:2014,q:"Which of the following is an electrophile?",o:{A:"NH₃",B:"H₂O",C:"BF₃",D:"R–NH₂"},a:"C",e:"BF₃ is an electrophile (electron pair acceptor) — B has empty p orbital. Others are nucleophiles.",ch:"Basic Principles of Organic",sub:"Chemistry",d:"medium"},
{id:"c47",y:2013,q:"Aldol condensation is given by:",o:{A:"HCHO",B:"CH₃CHO",C:"(CH₃)₃CCHO",D:"C₆H₅CHO"},a:"B",e:"Aldol condensation requires α-hydrogen. CH₃CHO has α-H. HCHO has no α-H; others also lack it.",ch:"Aldehydes, Ketones & Carboxylic Acids",sub:"Chemistry",d:"medium"},
{id:"c48",y:2012,q:"Electronic configuration of Cu is:",o:{A:"[Ar]3d⁹4s²",B:"[Ar]3d¹⁰4s¹",C:"[Ar]3d¹⁰4s²",D:"[Ar]3d⁸4s²"},a:"B",e:"Cu: extra stability of completely filled 3d¹⁰ → [Ar]3d¹⁰4s¹. Anomalous configuration.",ch:"d & f Block Elements",sub:"Chemistry",d:"medium"},
{id:"c49",y:2011,q:"Which cannot act as both oxidising and reducing agent?",o:{A:"H₂O₂",B:"H₂SO₄",C:"HNO₃",D:"F₂"},a:"D",e:"F₂ is the strongest oxidising agent. F has no higher oxidation state, so cannot be oxidised → only oxidising agent.",ch:"Redox Reactions",sub:"Chemistry",d:"medium"},
{id:"c50",y:2010,q:"Molar mass of a compound whose 2g dissolved in 100g benzene elevates bp by 0.52°C (Kb=2.6):",o:{A:"100 g/mol",B:"50 g/mol",C:"200 g/mol",D:"150 g/mol"},a:"A",e:"ΔTb = Kb × m = 2.6 × (2/M × 10) = 0.52 → M = 100 g/mol.",ch:"Solutions",sub:"Chemistry",d:"hard"},
{id:"c51",y:2009,q:"Which of the following is an example of shape-selective catalysis?",o:{A:"Wilkinson catalyst",B:"Ziegler-Natta catalyst",C:"Zeolites",D:"Nickel in hydrogenation"},a:"C",e:"Zeolites are shape-selective catalysts — only molecules fitting the pore size can enter and react.",ch:"Surface Chemistry",sub:"Chemistry",d:"medium"},
{id:"c52",y:2008,q:"In Victor Meyer test, primary alcohol gives:",o:{A:"Red colour",B:"Blue colour",C:"No colour",D:"Yellow colour"},a:"A",e:"Victor Meyer test: 1° alcohol → nitroalkane → red colour with FeSO₄/NaOH.",ch:"Alcohols, Phenols & Ethers",sub:"Chemistry",d:"hard"},
{id:"c53",y:2007,q:"Tollen's reagent gives positive test with:",o:{A:"Acetone",B:"Benzaldehyde",C:"Glucose",D:"Both B and C"},a:"D",e:"Tollen's (ammoniacal AgNO₃) detects aldehyde group. Both benzaldehyde and glucose have CHO.",ch:"Aldehydes, Ketones & Carboxylic Acids",sub:"Chemistry",d:"medium"},
{id:"c54",y:2006,q:"Which of the following is the weakest acid?",o:{A:"HF",B:"HCl",C:"HBr",D:"HI"},a:"A",e:"HF is weakest hydrohalic acid (pKa ~3.2). Bond strength: H–F strongest → least ionised.",ch:"Equilibrium",sub:"Chemistry",d:"medium"},
{id:"c55",y:2026,q:"Gabriel synthesis is used to prepare:",o:{A:"Secondary amines",B:"Primary amines",C:"Tertiary amines",D:"Quaternary ammonium salts"},a:"B",e:"Gabriel synthesis: phthalimide → N-alkylphthalimide → hydrolysis → primary amine (pure, no secondary/tertiary).",ch:"Amines",sub:"Chemistry",d:"medium"},
{id:"c56",y:2025,q:"Which of the following shows both Tyndall effect and Brownian motion?",o:{A:"True solution",B:"Colloidal solution",C:"Suspension",D:"Both B and C"},a:"B",e:"Colloidal solutions show Tyndall effect (light scattering by particles 1-100nm) and Brownian motion.",ch:"Surface Chemistry",sub:"Chemistry",d:"easy"},
{id:"c57",y:2024,q:"Fehling's solution is reduced by:",o:{A:"Sucrose",B:"Fructose",C:"Cellulose",D:"Starch"},a:"B",e:"Fructose (ketose) is a reducing sugar — reduces Fehling's solution despite being a ketone.",ch:"Biomolecules",sub:"Chemistry",d:"medium"},
{id:"c58",y:2023,q:"Werner's theory: the secondary valency of Co in [Co(NH₃)₆]³⁺ is:",o:{A:"3",B:"6",C:"3+6=9",D:"0"},a:"B",e:"Secondary valency = coordination number. [Co(NH₃)₆]³⁺ has 6 NH₃ ligands → CN = 6.",ch:"Coordination Compounds",sub:"Chemistry",d:"medium"},
{id:"c59",y:2022,q:"The IUPAC name of CH₃–CO–CH₂–CH₃ is:",o:{A:"Butanone",B:"Butan-2-one",C:"2-butanone",D:"Both A, B and C"},a:"D",e:"CH₃COCH₂CH₃ is butan-2-one. All three are correct names (butanone, butan-2-one, 2-butanone).",ch:"Aldehydes, Ketones & Carboxylic Acids",sub:"Chemistry",d:"easy"},
{id:"c60",y:2021,q:"Which is a biodegradable polymer?",o:{A:"Polythene",B:"PVC",C:"Nylon-6,6",D:"PHBV"},a:"D",e:"PHBV (polyhydroxybutyrate-co-hydroxyvalerate) is biodegradable. Others are non-biodegradable.",ch:"Polymers",sub:"Chemistry",d:"medium"},

// ── PHYSICS (60Q) ────────────────────────────────────────────────────────────
{id:"p1",y:2006,q:"Escape velocity from Earth's surface:",o:{A:"9.8 km/s",B:"11.2 km/s",C:"7.9 km/s",D:"6.4 km/s"},a:"B",e:"vₑ = √(2gR) = √(2×9.8×6.4×10⁶) ≈ 11.2 km/s. Must memorise.",ch:"Gravitation",sub:"Physics",d:"easy"},
{id:"p2",y:2007,q:"Body at rest breaks into two equal masses. They move:",o:{A:"Same direction",B:"Perpendicular directions",C:"Opposite directions, equal speeds",D:"Opposite directions, unequal speeds"},a:"C",e:"Initial momentum = 0. Equal masses → v₁ = −v₂ (equal and opposite).",ch:"Laws of Motion",sub:"Physics",d:"easy"},
{id:"p3",y:2008,q:"Dimensional formula of Planck's constant:",o:{A:"[ML²T⁻²]",B:"[ML²T⁻¹]",C:"[MLT⁻¹]",D:"[ML⁻¹T⁻²]"},a:"B",e:"h = E/ν = [ML²T⁻²]/[T⁻¹] = [ML²T⁻¹]. Same as angular momentum.",ch:"Units & Dimensions",sub:"Physics",d:"easy"},
{id:"p4",y:2009,q:"String holding stone in circular motion breaks. Stone moves:",o:{A:"Falls vertically",B:"Along the radius outward",C:"Along the tangent",D:"Spirals outward"},a:"C",e:"Newton's 1st law: without centripetal force, stone continues in straight line — tangent to circle.",ch:"Laws of Motion",sub:"Physics",d:"easy"},
{id:"p5",y:2010,q:"Light ray going from denser to rarer medium:",o:{A:"Bends towards the normal",B:"Bends away from the normal",C:"Passes straight through",D:"Always undergoes total internal reflection"},a:"B",e:"Denser → rarer: speed increases → bends away from normal (Snell's law).",ch:"Ray Optics",sub:"Physics",d:"easy"},
{id:"p6",y:2011,q:"Wire stretched to double its length. New resistance is:",o:{A:"Double",B:"4 times",C:"Half",D:"Unchanged"},a:"B",e:"R = ρL/A. L doubles, A halves (volume conserved) → R = ρ(2L)/(A/2) = 4R.",ch:"Current Electricity",sub:"Physics",d:"medium"},
{id:"p7",y:2012,q:"de Broglie wavelength of a particle with momentum p:",o:{A:"hp",B:"h/p",C:"p/h",D:"h/p²"},a:"B",e:"λ = h/p = h/mv. Foundation of matter-wave duality (de Broglie, 1924).",ch:"Dual Nature of Radiation",sub:"Physics",d:"easy"},
{id:"p8",y:2013,q:"In series LCR circuit, resonance occurs when:",o:{A:"XL > XC",B:"XL < XC",C:"XL = XC",D:"R = XL"},a:"C",e:"At resonance: XL = XC → Z = R (minimum). Current = V/R (maximum).",ch:"Alternating Current",sub:"Physics",d:"easy"},
{id:"p9",y:2014,q:"Two capacitors C in series vs parallel. Ratio Cs : Cp:",o:{A:"1:4",B:"2:1",C:"1:2",D:"4:1"},a:"A",e:"Series: C/2. Parallel: 2C. Ratio = C/2 : 2C = 1:4.",ch:"Electrostatic Potential & Capacitance",sub:"Physics",d:"medium"},
{id:"p10",y:2015,q:"Photon λ = 4×10⁻⁷m strikes metal (W = 2.13 eV). Max KE of electrons:",o:{A:"0.97 eV",B:"3.1 eV",C:"4.97 eV",D:"1.97 eV"},a:"A",e:"E = hc/λ ≈ 3.1 eV. KE = E − W = 3.1 − 2.13 = 0.97 eV.",ch:"Dual Nature of Radiation",sub:"Physics",d:"hard"},
{id:"p11",y:2016,q:"rms speed of gas molecules is proportional to:",o:{A:"√T",B:"T",C:"T²",D:"1/√T"},a:"A",e:"v_rms = √(3RT/M) ∝ √T. Doubling T increases v_rms by factor √2.",ch:"Kinetic Theory of Gases",sub:"Physics",d:"easy"},
{id:"p12",y:2017,q:"Drift velocity of electrons in a conductor:",o:{A:"v_d = I/(nAe)",B:"v_d = nAeI",C:"v_d = neA/I",D:"v_d = I/ne"},a:"A",e:"I = nAev_d → v_d = I/(nAe). n=number density, A=area, e=electron charge.",ch:"Current Electricity",sub:"Physics",d:"medium"},
{id:"p13",y:2018,q:"100W bulb glows for 2 hours. Energy consumed in kWh:",o:{A:"0.2 kWh",B:"0.02 kWh",C:"2 kWh",D:"0.5 kWh"},a:"A",e:"Energy = P × t = 100 W × 2 h = 200 Wh = 0.2 kWh.",ch:"Current Electricity",sub:"Physics",d:"easy"},
{id:"p14",y:2019,q:"Half-life of radioactive substance is 5 years. Fraction remaining after 20 years:",o:{A:"1/4",B:"1/8",C:"1/16",D:"1/2"},a:"C",e:"20 years = 4 half-lives. Fraction remaining = (1/2)⁴ = 1/16.",ch:"Nuclei",sub:"Physics",d:"easy"},
{id:"p15",y:2019,q:"YDSE: d=0.5mm, D=1m, λ=500nm. Fringe width:",o:{A:"0.5 mm",B:"1 mm",C:"2 mm",D:"0.25 mm"},a:"B",e:"β = λD/d = 500×10⁻⁹ × 1 / 0.5×10⁻³ = 10⁻³ m = 1 mm.",ch:"Wave Optics",sub:"Physics",d:"medium"},
{id:"p16",y:2020,q:"Charge Q at centre of a cube. Electric flux through one face:",o:{A:"Q/ε₀",B:"Q/6ε₀",C:"Q/8ε₀",D:"Q/24ε₀"},a:"B",e:"Gauss law: total flux = Q/ε₀. Cube has 6 identical faces → Q/6ε₀ per face.",ch:"Electric Charges & Fields",sub:"Physics",d:"medium"},
{id:"p17",y:2021,q:"Nucleus with highest binding energy per nucleon:",o:{A:"²H",B:"⁵⁶Fe",C:"²³⁵U",D:"⁴He"},a:"B",e:"⁵⁶Fe has ~8.8 MeV/nucleon — peak of binding energy curve — most stable nucleus.",ch:"Nuclei",sub:"Physics",d:"medium"},
{id:"p18",y:2022,q:"In SHM with amplitude A, KE = PE at displacement:",o:{A:"A/√2",B:"A/2",C:"A√2",D:"A/4"},a:"A",e:"½mω²(A²−x²) = ½mω²x² → A² − x² = x² → x = A/√2.",ch:"Oscillations",sub:"Physics",d:"hard"},
{id:"p19",y:2023,q:"NOR gate gives output 1 only when:",o:{A:"Both inputs = 1",B:"Any input = 1",C:"Both inputs = 0",D:"Inputs are different"},a:"C",e:"NOR = NOT(OR). Output is 1 only when both inputs are 0.",ch:"Semiconductor Electronics",sub:"Physics",d:"easy"},
{id:"p20",y:2024,q:"Convex lens forms real, inverted, same-size image. Object distance:",o:{A:"f",B:"2f",C:"Between f and 2f",D:"Beyond 2f"},a:"B",e:"Real + inverted + same size → object at 2F, image also at 2F on other side.",ch:"Ray Optics",sub:"Physics",d:"easy"},
{id:"p21",y:2025,q:"Transformer: 200 primary turns, 50 secondary turns, Vp = 220V. Secondary voltage:",o:{A:"880 V",B:"55 V",C:"110 V",D:"44 V"},a:"B",e:"Vs/Vp = Ns/Np → Vs = 220 × 50/200 = 55 V. Step-down transformer.",ch:"Electromagnetic Induction",sub:"Physics",d:"easy"},
{id:"p22",y:2026,q:"Magnetic field at centre of a circular current loop (radius r, current I):",o:{A:"μ₀I/2r",B:"μ₀I/r",C:"μ₀I/4r",D:"2μ₀I/r"},a:"A",e:"B = μ₀I/2r at centre of circular loop. Standard result — must memorise.",ch:"Moving Charges & Magnetism",sub:"Physics",d:"easy"},
{id:"p23",y:2021,q:"In Bohr model, kinetic energy of electron in nth orbit relative to total energy E:",o:{A:"KE = E",B:"KE = −E",C:"KE = 2E",D:"KE = E/2"},a:"B",e:"Total E = KE + PE. In Bohr: PE = 2E (total). So KE = E − 2E = −E.",ch:"Atoms",sub:"Physics",d:"hard"},
{id:"p24",y:2020,q:"Majority charge carriers in p-type semiconductor:",o:{A:"Electrons",B:"Holes",C:"Protons",D:"Neutrons"},a:"B",e:"p-type: doped with trivalent impurity (e.g., B) → holes as majority carriers.",ch:"Semiconductor Electronics",sub:"Physics",d:"easy"},
{id:"p25",y:2022,q:"Body thrown vertically up with speed u. Time of ascent : time of descent:",o:{A:"1:1",B:"1:2",C:"2:1",D:"Depends on u"},a:"A",e:"t_up = u/g = t_down (no air resistance). Ratio = 1:1.",ch:"Motion in Straight Line",sub:"Physics",d:"easy"},
{id:"p26",y:2023,q:"Mass doubled, velocity halved. New KE compared to original:",o:{A:"Same",B:"Half",C:"Double",D:"Quarter"},a:"B",e:"KE = ½mv². New = ½(2m)(v/2)² = mv²/4 = (½mv²)/2. KE halves.",ch:"Work, Energy & Power",sub:"Physics",d:"easy"},
{id:"p27",y:2024,q:"Phenomenon proving transverse nature of light:",o:{A:"Interference",B:"Diffraction",C:"Polarisation",D:"Reflection"},a:"C",e:"Only transverse waves can be polarised. Longitudinal waves cannot.",ch:"Wave Optics",sub:"Physics",d:"easy"},
{id:"p28",y:2025,q:"YDSE: slit separation halved, screen distance doubled. New fringe width:",o:{A:"2×",B:"4×",C:"Half",D:"Same"},a:"B",e:"β = λD/d → New β = λ(2D)/(d/2) = 4λD/d = 4β.",ch:"Wave Optics",sub:"Physics",d:"medium"},
{id:"p29",y:2026,q:"Dimensional formula of angular momentum:",o:{A:"[ML²T⁻¹]",B:"[MLT⁻¹]",C:"[ML²T⁻²]",D:"[ML⁻¹T⁻¹]"},a:"A",e:"L = mvr = kg⋅m/s⋅m = [ML²T⁻¹]. Same dimensions as Planck's constant h.",ch:"Units & Dimensions",sub:"Physics",d:"easy"},
{id:"p30",y:2020,q:"Convex lens f=20cm, real image at 60cm. Object distance:",o:{A:"30 cm",B:"40 cm",C:"60 cm",D:"15 cm"},a:"A",e:"1/v − 1/u = 1/f → 1/60 − 1/u = 1/20 → u = −30 cm.",ch:"Ray Optics",sub:"Physics",d:"medium"},
{id:"p31",y:2018,q:"rms speed of O₂ = rms speed of H₂ at 300K. Temperature of O₂:",o:{A:"2400 K",B:"600 K",C:"4800 K",D:"1200 K"},a:"C",e:"v_rms ∝ √(T/M). T_O₂/32 = 300/2 → T_O₂ = 4800 K.",ch:"Kinetic Theory of Gases",sub:"Physics",d:"hard"},
{id:"p32",y:2017,q:"Threshold frequency ν₀, incident light = 2ν₀. Max KE of photoelectrons:",o:{A:"hν₀",B:"2hν₀",C:"hν₀/2",D:"3hν₀"},a:"A",e:"KE = h(ν − ν₀) = h(2ν₀ − ν₀) = hν₀.",ch:"Dual Nature of Radiation",sub:"Physics",d:"easy"},
{id:"p33",y:2016,q:"Half-life = 30 min. Fraction remaining after 2 hours:",o:{A:"1/16",B:"1/8",C:"1/4",D:"1/32"},a:"A",e:"2h = 120 min = 4 half-lives → (1/2)⁴ = 1/16.",ch:"Nuclei",sub:"Physics",d:"easy"},
{id:"p34",y:2015,q:"Ohm's law is strictly valid for:",o:{A:"Semiconductors",B:"Vacuum tubes",C:"Metallic conductors at constant temperature",D:"Electrolytes"},a:"C",e:"Ohm's law (V=IR, linear I–V) holds for metallic conductors at constant temperature only.",ch:"Current Electricity",sub:"Physics",d:"easy"},
{id:"p35",y:2014,q:"EMF induced in a coil depends on:",o:{A:"Flux itself",B:"Rate of change of flux",C:"Resistance of coil",D:"Current in coil"},a:"B",e:"Faraday's law: EMF = −dΦ/dt. EMF depends on RATE of change of flux, not flux itself.",ch:"Electromagnetic Induction",sub:"Physics",d:"easy"},
{id:"p36",y:2013,q:"Electric potential at distance r from a point charge Q:",o:{A:"kQ/r²",B:"kQ/r",C:"kQ²/r",D:"kQ/r³"},a:"B",e:"V = kQ/r. Note: Electric field E = kQ/r² is different. Don't confuse the two.",ch:"Electrostatic Potential & Capacitance",sub:"Physics",d:"easy"},
{id:"p37",y:2022,q:"Which is a vector quantity?",o:{A:"Speed",B:"Distance",C:"Displacement",D:"Mass"},a:"C",e:"Displacement has both magnitude and direction → vector. Speed, distance, mass are scalars.",ch:"Motion in Straight Line",sub:"Physics",d:"easy"},
{id:"p38",y:2023,q:"Dimensions of torque (τ = F × d):",o:{A:"[ML²T⁻²]",B:"[MLT⁻²]",C:"[ML²T⁻³]",D:"[M²L²T⁻²]"},a:"A",e:"τ = F×d = [MLT⁻²][L] = [ML²T⁻²]. Same dimensions as energy (but different quantities).",ch:"Rotational Motion",sub:"Physics",d:"medium"},
{id:"p39",y:2024,q:"For isothermal expansion of an ideal gas, ΔU is:",o:{A:"ΔU > 0",B:"ΔU < 0",C:"ΔU = 0",D:"Q = 0"},a:"C",e:"Ideal gas: U depends only on T. Isothermal → ΔT = 0 → ΔU = 0. Therefore Q = W.",ch:"Thermodynamics",sub:"Physics",d:"medium"},
{id:"p40",y:2025,q:"Wavelength of light in medium of refractive index n=1.5 (λ_air=600nm):",o:{A:"900 nm",B:"400 nm",C:"600 nm",D:"300 nm"},a:"B",e:"λ_medium = λ_air/n = 600/1.5 = 400 nm. Speed and λ change; frequency stays same.",ch:"Ray Optics",sub:"Physics",d:"medium"},
{id:"p41",y:2026,q:"Quantity conserved in ALL types of collisions:",o:{A:"Kinetic energy",B:"Momentum",C:"Velocity",D:"Potential energy"},a:"B",e:"Linear momentum is conserved in all collisions. KE conserved only in elastic collisions.",ch:"Laws of Motion",sub:"Physics",d:"easy"},
{id:"p42",y:2021,q:"Exact expression for gravitational PE at height h above Earth:",o:{A:"mgh",B:"−mgh",C:"GMm/R",D:"−GMm/(R+h)"},a:"D",e:"U = −GMm/(R+h). mgh is only an approximation valid when h << R.",ch:"Gravitation",sub:"Physics",d:"medium"},
{id:"p43",y:2019,q:"Force on current-carrying wire in magnetic field B is maximum when:",o:{A:"θ = 0°",B:"θ = 90°",C:"θ = 45°",D:"θ = 180°"},a:"B",e:"F = BIL sinθ. Maximum when sinθ = 1, i.e., θ = 90° (current ⊥ B).",ch:"Moving Charges & Magnetism",sub:"Physics",d:"easy"},
{id:"p44",y:2018,q:"Power factor of a purely resistive AC circuit:",o:{A:"0",B:"0.5",C:"1",D:"Infinity"},a:"C",e:"PF = cosφ = R/Z. For purely resistive: Z = R, φ = 0 → cos0 = 1.",ch:"Alternating Current",sub:"Physics",d:"easy"},
{id:"p45",y:2020,q:"Which is NOT a property of electric field lines?",o:{A:"Start from positive charges",B:"End at negative charges",C:"Can intersect each other",D:"Perpendicular to conductor surface"},a:"C",e:"Field lines NEVER intersect — if they did, E would have two directions at that point, which is impossible.",ch:"Electric Charges & Fields",sub:"Physics",d:"easy"},
{id:"p46",y:2021,q:"A body falls freely from rest. Distance fallen in time t:",o:{A:"gt",B:"½gt",C:"½gt²",D:"gt²"},a:"C",e:"s = ut + ½at² = 0 + ½gt² = ½gt².",ch:"Motion in Straight Line",sub:"Physics",d:"easy"},
{id:"p47",y:2022,q:"Which physical quantity has the same dimensions as energy?",o:{A:"Power",B:"Torque",C:"Impulse",D:"Pressure"},a:"B",e:"Torque = [ML²T⁻²] = same as energy. Though they are different physical quantities.",ch:"Units & Dimensions",sub:"Physics",d:"medium"},
{id:"p48",y:2023,q:"During adiabatic expansion of an ideal gas:",o:{A:"Temperature increases",B:"Temperature decreases",C:"Temperature stays constant",D:"Internal energy increases"},a:"B",e:"Adiabatic: Q=0. Work done by gas → W>0. ΔU = Q − W = −W < 0 → temperature falls.",ch:"Thermodynamics",sub:"Physics",d:"medium"},
{id:"p49",y:2024,q:"Hydrogen atom: electron in first Bohr orbit has radius approximately:",o:{A:"0.529 nm",B:"0.529 Å",C:"0.529 cm",D:"0.529 mm"},a:"B",e:"Bohr radius a₀ = 0.529 Å = 52.9 pm. First orbit radius = a₀.",ch:"Atoms",sub:"Physics",d:"easy"},
{id:"p50",y:2025,q:"In a Young's double slit experiment, if white light is used:",o:{A:"Only central fringe is white, others are coloured",B:"All fringes are white",C:"All fringes are coloured",D:"No fringes are formed"},a:"A",e:"Central fringe: all λ overlap → white. Other fringes: different λ at different positions → coloured.",ch:"Wave Optics",sub:"Physics",d:"medium"},
{id:"p51",y:2020,q:"Magnetic force on a stationary charge in a magnetic field:",o:{A:"Acts along B",B:"Acts along velocity",C:"Is zero",D:"Is maximum"},a:"C",e:"F = qv×B. If v = 0 (stationary charge), F = 0. Magnetic force requires motion.",ch:"Moving Charges & Magnetism",sub:"Physics",d:"easy"},
{id:"p52",y:2019,q:"Which electromagnetic wave has the highest frequency?",o:{A:"Microwaves",B:"X-rays",C:"Gamma rays",D:"UV rays"},a:"C",e:"EM spectrum (increasing frequency): Radio < Micro < IR < Visible < UV < X-ray < Gamma.",ch:"EM Waves",sub:"Physics",d:"easy"},
{id:"p53",y:2018,q:"Minimum angle of deviation for a prism depends on:",o:{A:"Angle of prism only",B:"Refractive index only",C:"Both angle of prism and refractive index",D:"Incident angle only"},a:"C",e:"δmin = 2sin⁻¹(n sin(A/2)) − A. Depends on both A (angle of prism) and n (refractive index).",ch:"Ray Optics",sub:"Physics",d:"medium"},
{id:"p54",y:2017,q:"Which gate is called the universal gate?",o:{A:"OR",B:"AND",C:"NOT",D:"NAND"},a:"D",e:"NAND (and NOR) are universal gates — any logic circuit can be built using only NAND gates.",ch:"Semiconductor Electronics",sub:"Physics",d:"easy"},
{id:"p55",y:2016,q:"A proton and alpha particle have same KE. Ratio of their de Broglie wavelengths λp:λα:",o:{A:"1:2",B:"2:1",C:"1:1",D:"√2:1"},a:"B",e:"λ = h/p = h/√(2mKE). Same KE: λ ∝ 1/√m. λp/λα = √(mα/mp) = √4 = 2. Ratio = 2:1.",ch:"Dual Nature of Radiation",sub:"Physics",d:"hard"},
{id:"p56",y:2015,q:"For a transformer with 100% efficiency, if Np > Ns then:",o:{A:"Vs > Vp and Is < Ip",B:"Vs < Vp and Is > Ip",C:"Vs > Vp and Is > Ip",D:"Vs = Vp"},a:"B",e:"Step-down: Np > Ns → Vs < Vp. Power conservation: VpIp = VsIs → Is > Ip.",ch:"Electromagnetic Induction",sub:"Physics",d:"medium"},
{id:"p57",y:2014,q:"When a capacitor is fully charged and connected to a DC source, current in circuit:",o:{A:"Increases with time",B:"Is constant",C:"Decreases to zero",D:"Is zero from start"},a:"C",e:"Initially high current flows to charge capacitor. As charge builds, current decreases → zero when fully charged.",ch:"Electrostatic Potential & Capacitance",sub:"Physics",d:"medium"},
{id:"p58",y:2013,q:"Critical angle for total internal reflection depends on:",o:{A:"Refractive index of denser medium only",B:"Frequency of light only",C:"Refractive index of both media",D:"Angle of incidence"},a:"C",e:"sin(θc) = n₂/n₁. Critical angle depends on refractive indices of both media at the interface.",ch:"Ray Optics",sub:"Physics",d:"medium"},
{id:"p59",y:2012,q:"Photoelectric effect proves that light has:",o:{A:"Wave nature",B:"Particle nature",C:"Both wave and particle nature",D:"Neither"},a:"B",e:"Photoelectric effect explained only by photon (particle) theory. Wave theory cannot explain threshold frequency.",ch:"Dual Nature of Radiation",sub:"Physics",d:"easy"},
{id:"p60",y:2011,q:"A convex mirror always forms a:",o:{A:"Real, inverted, diminished image",B:"Virtual, erect, diminished image",C:"Real, erect, magnified image",D:"Virtual, inverted, enlarged image"},a:"B",e:"Convex mirror: image is always virtual, erect, and diminished. Used as rear-view mirror.",ch:"Ray Optics",sub:"Physics",d:"easy"},

// ── BIOLOGY (60Q) ────────────────────────────────────────────────────────────
{id:"b1",y:2006,q:"Crossing over during meiosis occurs at:",o:{A:"Zygotene",B:"Pachytene",C:"Diplotene",D:"Leptotene"},a:"B",e:"Crossing over occurs at pachytene stage of Prophase I — between non-sister chromatids at chiasmata.",ch:"Cell Cycle & Division",sub:"Biology",d:"easy"},
{id:"b2",y:2007,q:"The sugar present in DNA is:",o:{A:"Ribose",B:"Fructose",C:"Deoxyribose",D:"Galactose"},a:"C",e:"DNA contains 2'-deoxyribose. RNA contains ribose. The OH at 2' position is absent in DNA.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b3",y:2008,q:"Organism showing holozoic nutrition:",o:{A:"Amoeba",B:"Euglena",C:"Paramecium",D:"Plasmodium"},a:"A",e:"Amoeba shows holozoic nutrition — ingests solid food particles using pseudopodia.",ch:"Animal Kingdom",sub:"Biology",d:"easy"},
{id:"b4",y:2009,q:"Meselson and Stahl proved DNA replication is:",o:{A:"Conservative",B:"Semi-conservative",C:"Dispersive",D:"Random"},a:"B",e:"CsCl density gradient showed hybrid DNA (intermediate density) after 1st generation → semi-conservative.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b5",y:2010,q:"AIDS is caused by:",o:{A:"Bacteria",B:"HIV (retrovirus)",C:"Protozoa",D:"Fungus"},a:"B",e:"HIV (Human Immunodeficiency Virus) — retrovirus that attacks and destroys CD4⁺ T-helper cells.",ch:"Human Health & Disease",sub:"Biology",d:"easy"},
{id:"b6",y:2011,q:"Restriction endonucleases recognise and cut at:",o:{A:"Promoter sequences",B:"Palindromic sequences",C:"Enhancer sequences",D:"Introns"},a:"B",e:"Restriction enzymes recognise palindromic sequences — same sequence on both strands read 5'→3'.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"easy"},
{id:"b7",y:2012,q:"Example of ex situ conservation:",o:{A:"Wildlife sanctuary",B:"National park",C:"Biosphere reserve",D:"Seed bank"},a:"D",e:"Ex situ = outside natural habitat. Seed banks, zoological parks, botanical gardens.",ch:"Biodiversity & Conservation",sub:"Biology",d:"easy"},
{id:"b8",y:2013,q:"Emergency hormone (fight or flight):",o:{A:"Thyroxine",B:"Insulin",C:"Adrenaline",D:"Cortisol"},a:"C",e:"Adrenaline (epinephrine) from adrenal medulla → increases heart rate, BP → fight or flight.",ch:"Chemical Coordination & Integration",sub:"Biology",d:"easy"},
{id:"b9",y:2014,q:"Functional unit of gene expression in prokaryotes:",o:{A:"Single gene",B:"Operon",C:"Promoter alone",D:"Cistron"},a:"B",e:"Operon (Jacob-Monod model): structural genes + operator + promoter under coordinated regulation.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b10",y:2015,q:"In sickle cell anaemia, glutamic acid is replaced by:",o:{A:"Alanine",B:"Valine",C:"Glycine",D:"Leucine"},a:"B",e:"6th amino acid of β-globin changes: Glu → Val due to single base substitution (A→T) in codon 6.",ch:"Principles of Inheritance & Variation",sub:"Biology",d:"medium"},
{id:"b11",y:2016,q:"Plant hormone that promotes cell division:",o:{A:"Auxin",B:"Gibberellin",C:"Cytokinin",D:"ABA"},a:"C",e:"Cytokinin promotes cytokinesis and cell division. Named for their ability to cause cytokinesis.",ch:"Plant Growth & Development",sub:"Biology",d:"easy"},
{id:"b12",y:2017,q:"Okazaki fragments are formed on:",o:{A:"Leading strand",B:"Lagging strand",C:"Both strands",D:"Template strand only"},a:"B",e:"Lagging strand is synthesised discontinuously as short Okazaki fragments due to antiparallel nature of DNA.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b13",y:2018,q:"Gene encoding Bt toxin in Bacillus thuringiensis:",o:{A:"nif gene",B:"cry gene",C:"Ti plasmid gene",D:"vir gene"},a:"B",e:"cry (crystal) genes encode Cry proteins — δ-endotoxins (Bt toxins) toxic to specific insects.",ch:"Biotechnology & Its Applications",sub:"Biology",d:"easy"},
{id:"b14",y:2019,q:"Cancer cells do NOT show:",o:{A:"Loss of contact inhibition",B:"Anchorage independence",C:"Unlimited proliferation",D:"Increased apoptosis"},a:"D",e:"Cancer cells evade apoptosis (programmed cell death) — apoptosis is decreased, not increased.",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b15",y:2019,q:"ABO blood group is an example of:",o:{A:"Codominance only",B:"Multiple allelism only",C:"Both codominance and multiple allelism",D:"Incomplete dominance"},a:"C",e:"3 alleles (Iᴬ, Iᴮ, i) = multiple allelism. Iᴬ and Iᴮ are codominant → AB blood group.",ch:"Principles of Inheritance & Variation",sub:"Biology",d:"hard"},
{id:"b16",y:2020,q:"Central dogma of molecular biology:",o:{A:"DNA → Protein → RNA",B:"RNA → DNA → Protein",C:"DNA → RNA → Protein",D:"Protein → RNA → DNA"},a:"C",e:"Central dogma (Crick, 1958): DNA → (transcription) → RNA → (translation) → Protein.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b17",y:2021,q:"Most abundant type of RNA in the cell:",o:{A:"mRNA",B:"tRNA",C:"rRNA",D:"hnRNA"},a:"C",e:"rRNA constitutes ~80% of total cellular RNA. It is the structural and functional component of ribosomes.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b18",y:2022,q:"Genetic code is NOT:",o:{A:"Universal",B:"Degenerate",C:"Non-overlapping",D:"Ambiguous"},a:"D",e:"Genetic code is unambiguous — each codon codes for only ONE amino acid. The reverse is not true (degeneracy).",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"hard"},
{id:"b19",y:2023,q:"Satellite DNA is useful in DNA fingerprinting because it is:",o:{A:"Present in all body cells",B:"Highly repeated, polymorphic, individual-specific",C:"Present only in sex chromosomes",D:"Easily amplified by PCR"},a:"B",e:"Satellite DNA: highly repetitive, non-coding sequences with individual-specific variation in repeat number.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b20",y:2024,q:"Only gaseous plant hormone:",o:{A:"Auxin",B:"Gibberellin",C:"Cytokinin",D:"Ethylene"},a:"D",e:"Ethylene is the only gaseous plant hormone. Promotes fruit ripening, abscission, senescence.",ch:"Plant Growth & Development",sub:"Biology",d:"easy"},
{id:"b21",y:2025,q:"Type of immunity from colostrum (mother's milk) for newborn:",o:{A:"Active natural",B:"Passive natural",C:"Active artificial",D:"Passive artificial"},a:"B",e:"Colostrum: maternal IgA antibodies → passive (baby doesn't produce them) + natural (not from vaccine).",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b22",y:2026,q:"Chromosomes align at the metaphase plate during:",o:{A:"Prophase",B:"Anaphase",C:"Metaphase",D:"Telophase"},a:"C",e:"Metaphase: chromosomes maximally condensed, aligned at equatorial plate. Best stage for karyotyping.",ch:"Cell Cycle & Division",sub:"Biology",d:"easy"},
{id:"b23",y:2022,q:"Which does NOT carry out biological nitrogen fixation?",o:{A:"Rhizobium",B:"Azotobacter",C:"Nitrosomonas",D:"Nostoc"},a:"C",e:"Nitrosomonas: nitrification (NH₃→NO₂⁻), NOT N₂ fixation. Others fix atmospheric N₂.",ch:"Ecosystem",sub:"Biology",d:"medium"},
{id:"b24",y:2021,q:"Turner syndrome (45, XO) is an example of:",o:{A:"Aneuploidy",B:"Polyploidy",C:"Euploidy",D:"Deletion"},a:"A",e:"Aneuploidy: abnormal number of individual chromosomes. 45,XO = monosomy (2n−1).",ch:"Principles of Inheritance & Variation",sub:"Biology",d:"hard"},
{id:"b25",y:2020,q:"Which immunoglobulin crosses the placenta?",o:{A:"IgA",B:"IgM",C:"IgG",D:"IgE"},a:"C",e:"IgG is the only immunoglobulin that crosses the placenta → provides passive immunity to the foetus.",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b26",y:2019,q:"Anticodon on tRNA pairs with:",o:{A:"The amino acid it carries",B:"The codon on mRNA",C:"The template DNA strand",D:"rRNA"},a:"B",e:"Anticodon (tRNA) is complementary and antiparallel to codon (mRNA). This is key for translation.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b27",y:2018,q:"Glycolysis occurs in:",o:{A:"Mitochondrial matrix",B:"Inner mitochondrial membrane",C:"Cytoplasm",D:"Nucleus"},a:"C",e:"Glycolysis = entirely cytoplasmic. Krebs cycle = mitochondrial matrix. ETC = inner membrane.",ch:"Respiration in Plants",sub:"Biology",d:"easy"},
{id:"b28",y:2017,q:"Bt toxin kills insects by:",o:{A:"Inhibiting protein synthesis",B:"Creating pores in gut epithelium",C:"Blocking nerve impulses",D:"Destroying membrane lipids"},a:"B",e:"Cry protein: activated in alkaline insect gut → binds epithelial receptors → pores → cell lysis → death.",ch:"Biotechnology & Its Applications",sub:"Biology",d:"medium"},
{id:"b29",y:2016,q:"Main replicative DNA polymerase in prokaryotes:",o:{A:"DNA ligase",B:"Helicase",C:"DNA polymerase III",D:"Primase"},a:"C",e:"DNA pol III = main replicative enzyme (high processivity). Pol I removes RNA primers.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b30",y:2015,q:"Which is the most totipotent cell?",o:{A:"Leaf mesophyll cell",B:"Pollen grain",C:"Zygote",D:"Xylem vessel element"},a:"C",e:"Zygote is the ultimate totipotent cell — can develop into a complete organism.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"easy"},
{id:"b31",y:2014,q:"Carrier mother × normal father. Percentage of haemophilic sons:",o:{A:"25%",B:"50%",C:"100%",D:"0%"},a:"B",e:"Mother: X^H X^h. Father: X^H Y. Sons: X^H Y (normal) or X^h Y (haemophilic) → 50% of sons.",ch:"Principles of Inheritance & Variation",sub:"Biology",d:"medium"},
{id:"b32",y:2013,q:"Correct statement about mitosis:",o:{A:"Reduces chromosome number by half",B:"Crossing over occurs in prophase I",C:"Produces 4 haploid daughter cells",D:"Produces 2 genetically identical diploid cells"},a:"D",e:"Mitosis produces 2 identical diploid daughter cells. Meiosis reduces chromosome number.",ch:"Cell Cycle & Division",sub:"Biology",d:"easy"},
{id:"b33",y:2012,q:"P-site (peptidyl site) in ribosome holds:",o:{A:"Incoming aminoacyl-tRNA",B:"tRNA carrying the growing polypeptide",C:"Discharged tRNA leaving ribosome",D:"mRNA only"},a:"B",e:"P-site: tRNA with growing polypeptide chain. A-site: aminoacyl-tRNA. E-site: exit for discharged tRNA.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b34",y:2011,q:"Net ATP produced per glucose in aerobic respiration (NCERT value):",o:{A:"2",B:"36",C:"38",D:"30"},a:"B",e:"NCERT gives 36 ATP net per glucose in eukaryotic aerobic respiration.",ch:"Respiration in Plants",sub:"Biology",d:"easy"},
{id:"b35",y:2010,q:"Which is NOT a vestigial organ in humans?",o:{A:"Coccyx (tailbone)",B:"Wisdom teeth",C:"Ear muscles",D:"Thyroid gland"},a:"D",e:"Thyroid gland is fully functional. Coccyx, wisdom teeth, and extrinsic ear muscles are vestigial.",ch:"Evolution",sub:"Biology",d:"easy"},
{id:"b36",y:2009,q:"Vitamin synthesised in human skin by UV radiation:",o:{A:"Vitamin A",B:"Vitamin B₁₂",C:"Vitamin C",D:"Vitamin D"},a:"D",e:"UV light converts 7-dehydrocholesterol → Vitamin D₃ (cholecalciferol) in skin. Needed for Ca absorption.",ch:"Chemical Coordination & Integration",sub:"Biology",d:"easy"},
{id:"b37",y:2008,q:"nif genes are responsible for:",o:{A:"Nitrogen fixation",B:"Nodule formation",C:"Protein synthesis",D:"Photosynthesis"},a:"A",e:"nif (nitrogen fixation) genes encode the nitrogenase enzyme complex in N₂-fixing bacteria.",ch:"Ecosystem",sub:"Biology",d:"medium"},
{id:"b38",y:2007,q:"A test cross is:",o:{A:"Cross between two heterozygotes",B:"Dominant phenotype × homozygous recessive",C:"Cross between two homozygous dominants",D:"F₁ × F₁"},a:"B",e:"Test cross (× tt): 1:1 ratio → parent is heterozygous; all dominant → parent is homozygous dominant.",ch:"Principles of Inheritance & Variation",sub:"Biology",d:"easy"},
{id:"b39",y:2025,q:"Vectors used in recombinant DNA technology include:",o:{A:"Bacteriophages only",B:"Plasmids only",C:"Both plasmids and bacteriophages",D:"Retroviruses only"},a:"C",e:"Both plasmids (e.g., pBR322) and bacteriophages (e.g., λ phage) serve as cloning vectors.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"easy"},
{id:"b40",y:2024,q:"Hardy-Weinberg equilibrium: allele frequencies remain constant when:",o:{A:"Mutation occurs frequently",B:"No evolutionary forces act on the population",C:"Natural selection acts",D:"Population is very small"},a:"B",e:"H-W: constant allele frequencies in absence of mutation, selection, drift, migration, non-random mating.",ch:"Evolution",sub:"Biology",d:"medium"},
{id:"b41",y:2023,q:"Which disease is caused by a virus?",o:{A:"Late blight of potato",B:"Tobacco mosaic disease",C:"Citrus canker",D:"Crown gall disease"},a:"B",e:"Tobacco Mosaic Disease caused by TMV. Late blight = Phytophthora (oomycete). Citrus canker = bacteria.",ch:"Human Health & Disease",sub:"Biology",d:"easy"},
{id:"b42",y:2022,q:"Synapsis (pairing of homologous chromosomes) occurs at:",o:{A:"Leptotene",B:"Zygotene",C:"Pachytene",D:"Diplotene"},a:"B",e:"Synapsis at zygotene. Crossing over at pachytene. Chiasmata visible at diplotene.",ch:"Cell Cycle & Division",sub:"Biology",d:"medium"},
{id:"b43",y:2021,q:"Site of light reactions (photosystems) in chloroplast:",o:{A:"Outer membrane",B:"Inner membrane",C:"Stroma",D:"Thylakoid membrane"},a:"D",e:"Light reactions occur on thylakoid membranes. Calvin cycle (dark reactions) occurs in stroma.",ch:"Photosynthesis",sub:"Biology",d:"easy"},
{id:"b44",y:2020,q:"Which type of RNA carries amino acids to the ribosome?",o:{A:"mRNA",B:"rRNA",C:"tRNA",D:"hnRNA"},a:"C",e:"tRNA (transfer RNA) carries specific amino acids to ribosome. Anticodon pairs with mRNA codon.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"easy"},
{id:"b45",y:2019,q:"Apical dominance is caused by:",o:{A:"Cytokinin from roots",B:"Gibberellin from stem",C:"Auxin from apical bud",D:"Ethylene from fruits"},a:"C",e:"Auxin from apical bud inhibits growth of lateral buds. Removing apical bud → lateral buds grow.",ch:"Plant Growth & Development",sub:"Biology",d:"easy"},
{id:"b46",y:2018,q:"Insulin is produced by:",o:{A:"Liver (hepatocytes)",B:"Pancreatic β-cells (islets of Langerhans)",C:"Kidney (juxtaglomerular cells)",D:"Adrenal cortex"},a:"B",e:"Insulin: β-cells of islets of Langerhans. Glucagon: α-cells. Both regulate blood glucose.",ch:"Chemical Coordination & Integration",sub:"Biology",d:"easy"},
{id:"b47",y:2017,q:"Reverse transcriptase enzyme is found in:",o:{A:"Bacteria",B:"Bacteriophages",C:"Retroviruses",D:"Fungi"},a:"C",e:"Retroviruses (HIV, HTLV) use reverse transcriptase to convert RNA genome → DNA. Basis of HIV replication.",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b48",y:2016,q:"Main gas causing acid rain:",o:{A:"CO₂",B:"SO₂",C:"N₂",D:"O₃"},a:"B",e:"SO₂ + H₂O → H₂SO₃/H₂SO₄ = acid rain. NOₓ also contributes. CO₂ causes global warming, not acid rain.",ch:"Environmental Issues",sub:"Biology",d:"easy"},
{id:"b49",y:2015,q:"Montreal Protocol (1987) deals with:",o:{A:"Global warming and CO₂ emissions",B:"Ozone layer depletion",C:"Acid rain",D:"River water pollution"},a:"B",e:"Montreal Protocol: international treaty to phase out CFCs and other ozone-depleting substances.",ch:"Environmental Issues",sub:"Biology",d:"easy"},
{id:"b50",y:2014,q:"Pyramid of energy is always:",o:{A:"Inverted",B:"Upright",C:"Spindle-shaped",D:"Can be either upright or inverted"},a:"B",e:"Energy pyramid ALWAYS upright — energy decreases at each trophic level (10% rule). Cannot be inverted.",ch:"Ecosystem",sub:"Biology",d:"medium"},
{id:"b51",y:2013,q:"Advantage of bioreactor over shake flask:",o:{A:"Can maintain higher temperature",B:"Provides optimal + monitored conditions for large-scale production",C:"Uses less oxygen",D:"Contains more microorganisms"},a:"B",e:"Bioreactor: controlled pH, temperature, O₂, nutrients, agitation → optimal large-scale production.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"medium"},
{id:"b52",y:2012,q:"Filariasis (elephantiasis) is caused by:",o:{A:"Plasmodium vivax",B:"Wuchereria bancrofti",C:"Entamoeba histolytica",D:"Ascaris lumbricoides"},a:"B",e:"Wuchereria bancrofti (filarial worm) causes filariasis/elephantiasis. Vector: Culex mosquito.",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b53",y:2011,q:"PCR (Polymerase Chain Reaction) uses:",o:{A:"RNA polymerase",B:"Taq DNA polymerase",C:"Primase",D:"Helicase only"},a:"B",e:"Taq polymerase (from Thermus aquaticus): thermostable, survives 95°C denaturation step in PCR.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"easy"},
{id:"b54",y:2010,q:"Golden rice is genetically engineered to produce:",o:{A:"Vitamin C",B:"Vitamin B₁₂",C:"β-carotene (provitamin A)",D:"Vitamin D"},a:"C",e:"Golden rice: expresses β-carotene in endosperm (using daffodil + bacterial genes) to address VAD.",ch:"Biotechnology & Its Applications",sub:"Biology",d:"easy"},
{id:"b55",y:2026,q:"Which is a complete nucleotide?",o:{A:"Adenine (base)",B:"Deoxyribose (sugar)",C:"AMP (Adenosine monophosphate)",D:"Phosphoric acid"},a:"C",e:"Nucleotide = nitrogenous base + pentose sugar + phosphate group. AMP = adenine + ribose + phosphate.",ch:"Molecular Basis of Inheritance",sub:"Biology",d:"medium"},
{id:"b56",y:2025,q:"Active immunity differs from passive immunity because:",o:{A:"Active immunity provides shorter protection",B:"In active immunity, the body produces its own antibodies and memory cells",C:"Passive immunity involves memory cell formation",D:"Active immunity comes from mother"},a:"B",e:"Active: own antibodies + memory cells (long-lasting). Passive: ready-made antibodies (temporary, no memory).",ch:"Human Health & Disease",sub:"Biology",d:"medium"},
{id:"b57",y:2024,q:"Amensalism is an interaction where:",o:{A:"Both species benefit",B:"One species is harmed, the other is unaffected",C:"One benefits, the other is harmed",D:"Both are harmed"},a:"B",e:"Amensalism: one harmed, other unaffected. Example: Penicillium inhibits bacteria; bacteria don't affect Penicillium.",ch:"Organisms & Populations",sub:"Biology",d:"medium"},
{id:"b58",y:2023,q:"Totipotency in plants was demonstrated experimentally by:",o:{A:"Griffith",B:"Avery, MacLeod and McCarty",C:"F.C. Steward",D:"Meselson and Stahl"},a:"C",e:"F.C. Steward (1958) grew a complete carrot plant from isolated phloem cells → proved totipotency.",ch:"Biotechnology: Principles & Processes",sub:"Biology",d:"medium"},
{id:"b59",y:2022,q:"'Richness of species' in an area refers to which type of biodiversity?",o:{A:"Genetic diversity",B:"Species diversity",C:"Ecosystem diversity",D:"Community diversity"},a:"B",e:"Species diversity = number and relative abundance of species. Most commonly discussed type of biodiversity.",ch:"Biodiversity & Conservation",sub:"Biology",d:"easy"},
{id:"b60",y:2021,q:"Corpus luteum mainly secretes:",o:{A:"Oestrogen only",B:"Progesterone (mainly)",C:"Luteinising hormone (LH)",D:"Follicle stimulating hormone (FSH)"},a:"B",e:"Corpus luteum (post-ovulation): mainly progesterone → maintains uterine lining for implantation.",ch:"Human Reproduction",sub:"Biology",d:"medium"},

// ── ADDITIONAL BIOLOGY QS TO REACH 90Q FULL MOCK ──────────────────────────
{id:"bx1",y:2017,q:"Which pigment is present in Photosystem I?",o:{A:"Chlorophyll b",B:"P700 (Chlorophyll a)",C:"P680 (Chlorophyll a)",D:"Xanthophyll"},a:"B",e:"PS I has P700 (Chl a with absorption max at 700nm). PS II has P680. PS I produces NADPH; PS II splits water.",ch:"Photosynthesis",sub:"Biology",d:"medium"},
{id:"bx2",y:2020,q:"The first stable product of C3 photosynthesis (Calvin cycle) is:",o:{A:"Glucose",B:"Pyruvate",C:"3-phosphoglycerate (3-PGA)",D:"Oxaloacetate"},a:"C",e:"CO₂ + RuBP → 2 molecules of 3-PGA (3-carbon compound). This is the first stable product in C3 plants.",ch:"Photosynthesis",sub:"Biology",d:"medium"},
{id:"bx3",y:2023,q:"In organisms showing commensalism:",o:{A:"Both species benefit",B:"One benefits, the other is neither helped nor harmed",C:"One benefits, the other is harmed",D:"Both are harmed"},a:"B",e:"Commensalism: one species benefits (+), the other is unaffected (0). Example: barnacles on whales, orchids on trees.",ch:"Organisms & Populations",sub:"Biology",d:"easy"},
{id:"bx4",y:2021,q:"Which of the following represents an r-selected species?",o:{A:"Elephants",B:"Humans",C:"Bacteria",D:"Whales"},a:"C",e:"r-selected: small body size, rapid reproduction, short lifespan, many offspring with little parental care. Bacteria are classic example.",ch:"Organisms & Populations",sub:"Biology",d:"medium"},
{id:"bx5",y:2019,q:"Protista includes organisms that are:",o:{A:"Prokaryotic only",B:"Eukaryotic and mostly unicellular",C:"Multicellular plants",D:"Acellular"},a:"B",e:"Kingdom Protista: eukaryotic, mostly unicellular. Includes algae (except blue-green), protozoans, slime moulds.",ch:"Biological Classification",sub:"Biology",d:"easy"},
{id:"bx6",y:2022,q:"The silica shells found in diatoms are called:",o:{A:"Frustules",B:"Pellicle",C:"Theca",D:"Test"},a:"A",e:"Diatom cell walls (frustules) are made of silica. They are bilaterally symmetrical and have two overlapping halves.",ch:"Biological Classification",sub:"Biology",d:"medium"},
{id:"bx7",y:2018,q:"Animal kingdom: Notochord is present in all chordates. Which of the following is NOT a feature of all chordates?",o:{A:"Notochord",B:"Dorsal nerve cord",C:"Pharyngeal gill slits",D:"Four-chambered heart"},a:"D",e:"Four-chambered heart is only in birds and mammals. Notochord, dorsal hollow nerve cord, and pharyngeal gill slits are features of ALL chordates.",ch:"Animal Kingdom",sub:"Biology",d:"medium"},
{id:"bx8",y:2021,q:"Which invertebrate phylum has the largest number of species?",o:{A:"Mollusca",B:"Echinodermata",C:"Arthropoda",D:"Annelida"},a:"C",e:"Arthropoda is the largest animal phylum — includes insects, crustaceans, arachnids (~1 million+ species). 2/3 of all animals are arthropods.",ch:"Animal Kingdom",sub:"Biology",d:"easy"},
{id:"bx9",y:2016,q:"Biomolecules — which bond links amino acids in a protein?",o:{A:"Glycosidic bond",B:"Peptide bond",C:"Phosphodiester bond",D:"Hydrogen bond"},a:"B",e:"Peptide bond: formed between –COOH of one amino acid and –NH₂ of the next with loss of water (condensation reaction).",ch:"Biomolecules",sub:"Biology",d:"easy"},
{id:"bx10",y:2019,q:"Which enzyme is called the 'molecular motor' of the cell?",o:{A:"Amylase",B:"ATPase",C:"RNA polymerase",D:"DNA helicase"},a:"B",e:"ATPase/ATP synthase (F₁F₀ ATPase) in inner mitochondrial membrane uses proton gradient to synthesize ATP — literally rotates like a motor.",ch:"Biomolecules",sub:"Biology",d:"hard"},
{id:"bx11",y:2014,q:"Secondary structure of protein refers to:",o:{A:"Sequence of amino acids",B:"α-helix and β-pleated sheet",C:"3D folding of the polypeptide",D:"Association of multiple subunits"},a:"B",e:"Primary = AA sequence. Secondary = α-helix and β-pleated sheet (H-bonds between backbone groups). Tertiary = 3D. Quaternary = subunits.",ch:"Biomolecules",sub:"Biology",d:"medium"},
{id:"bx12",y:2020,q:"Capacitation of sperms occurs in:",o:{A:"Testis",B:"Epididymis",C:"Female reproductive tract",D:"Seminal vesicle"},a:"C",e:"Capacitation: physiological change in sperm after entering female reproductive tract — makes sperm capable of fertilising the egg.",ch:"Human Reproduction",sub:"Biology",d:"medium"},
{id:"bx13",y:2023,q:"The correct sequence of embryonic development after fertilisation is:",o:{A:"Zygote → Morula → Blastula → Gastrula",B:"Zygote → Blastula → Morula → Gastrula",C:"Zygote → Gastrula → Morula → Blastula",D:"Morula → Zygote → Blastula → Gastrula"},a:"A",e:"Fertilisation → Zygote → cleavage → Morula (solid ball) → Blastula/Blastocyst (hollow) → implantation → Gastrula (3 germ layers).",ch:"Human Reproduction",sub:"Biology",d:"medium"},

// ── ADDED QUESTIONS FOR MISSING CHAPTERS ──
{id:"cm1",y:2015,q:"Which gas law states that at constant temperature, pressure of a fixed amount of gas is inversely proportional to its volume?",o:{A:"Charles' law",B:"Boyle's law",C:"Gay-Lussac's law",D:"Avogadro's law"},a:"B",e:"Boyle's law: P ∝ 1/V at constant T and n. PV = constant.",ch:"States of Matter",sub:"Chemistry",d:"easy"},
{id:"cm2",y:2018,q:"Intermolecular forces responsible for the high boiling point of water are:",o:{A:"London dispersion forces",B:"Dipole-dipole forces",C:"Hydrogen bonds",D:"Covalent bonds"},a:"C",e:"Water has extensive hydrogen bonding (O–H···O) which requires large energy to break → high bp (100°C).",ch:"States of Matter",sub:"Chemistry",d:"easy"},
{id:"cm3",y:2021,q:"Critical temperature of a gas is the temperature:",o:{A:"At which gas solidifies",B:"Above which gas cannot be liquefied regardless of pressure",C:"At which gas has maximum volume",D:"At which gas pressure is zero"},a:"B",e:"Above critical temperature (Tc), no amount of pressure can liquefy a gas. CO₂: Tc = 31.1°C.",ch:"States of Matter",sub:"Chemistry",d:"medium"},
{id:"cm4",y:2016,q:"The element with highest electronegativity is:",o:{A:"Oxygen",B:"Nitrogen",C:"Chlorine",D:"Fluorine"},a:"D",e:"Fluorine has highest electronegativity (3.98 on Pauling scale). It's the most electronegative element.",ch:"Periodic Table & Periodicity",sub:"Chemistry",d:"easy"},
{id:"cm5",y:2019,q:"Atomic radius generally decreases across a period because:",o:{A:"Number of shells increases",B:"Nuclear charge increases while electrons are added to the same shell",C:"Electron-electron repulsion decreases",D:"Shielding effect increases"},a:"B",e:"Across a period: nuclear charge (Z) increases but electrons go into same shell → increased attraction → smaller radius.",ch:"Periodic Table & Periodicity",sub:"Chemistry",d:"hard"},
{id:"cm6",y:2022,q:"Which of the following has the highest electron gain enthalpy (most negative)?",o:{A:"F",B:"Cl",C:"O",D:"S"},a:"B",e:"Cl has highest electron gain enthalpy (−349 kJ/mol). F is less due to its small size causing electron repulsion.",ch:"Periodic Table & Periodicity",sub:"Chemistry",d:"medium"},
{id:"cm7",y:2014,q:"Which property of hydrogen makes it unique?",o:{A:"It can act as both oxidising and reducing agent",B:"It resembles both alkali metals and halogens",C:"It exists as diatomic molecule",D:"It is lightest element"},a:"B",e:"H resembles alkali metals (loses e⁻ → H⁺) AND halogens (gains e⁻ → H⁻). This dual nature is unique.",ch:"Hydrogen",sub:"Chemistry",d:"medium"},
{id:"cm8",y:2020,q:"Heavy water (D₂O) is used as:",o:{A:"Rocket fuel",B:"Moderator in nuclear reactors",C:"Oxidising agent",D:"Reducing agent"},a:"B",e:"D₂O (deuterium oxide) is used as a moderator in nuclear reactors to slow neutrons without absorbing them.",ch:"Hydrogen",sub:"Chemistry",d:"easy"},
{id:"cm9",y:2017,q:"Boron is a:",o:{A:"Metal",B:"Non-metal",C:"Metalloid",D:"Noble gas"},a:"C",e:"Boron is a metalloid (semimetal) — has properties between metals and non-metals. Used in semiconductors.",ch:"p-Block Elements (Gr 13-14)",sub:"Chemistry",d:"easy"},
{id:"cm10",y:2023,q:"Which of the following is an electron deficient compound?",o:{A:"NH₃",B:"BF₃",C:"PH₃",D:"H₂O"},a:"B",e:"BF₃: B has only 6 electrons in valence shell (no lone pair) → electron deficient. Acts as Lewis acid.",ch:"p-Block Elements (Gr 13-14)",sub:"Chemistry",d:"medium"},
{id:"cm11",y:2019,q:"Carbon can form long chain compounds due to the property called:",o:{A:"Isomerism",B:"Catenation",C:"Allotropy",D:"Polymerisation"},a:"B",e:"Catenation: carbon's ability to form long chains with itself due to strong and stable C–C bonds.",ch:"p-Block Elements (Gr 13-14)",sub:"Chemistry",d:"easy"},
{id:"pm1",y:2015,q:"A projectile is fired at 45°. The ratio of its range to maximum height is:",o:{A:"1:1",B:"4:1",C:"2:1",D:"1:2"},a:"B",e:"Range R = u²sin2θ/g. Max height H = u²sin²θ/2g. For θ=45°: R/H = 4. Ratio = 4:1.",ch:"Motion in a Plane",sub:"Physics",d:"medium"},
{id:"pm2",y:2018,q:"A body moves in a circular path. The work done by centripetal force is:",o:{A:"Maximum",B:"Zero",C:"Negative",D:"Positive"},a:"B",e:"Centripetal force is always perpendicular to velocity (displacement) → W = F·d·cos90° = 0.",ch:"Motion in a Plane",sub:"Physics",d:"easy"},
{id:"pm3",y:2021,q:"In uniform circular motion, which quantity remains constant?",o:{A:"Velocity",B:"Acceleration",C:"Speed",D:"Momentum"},a:"C",e:"In UCM: speed is constant (magnitude of velocity). But velocity, acceleration, and momentum all change direction continuously.",ch:"Motion in a Plane",sub:"Physics",d:"easy"},
{id:"pm4",y:2016,q:"Coefficient of linear expansion (α) is related to coefficient of volume expansion (γ) by:",o:{A:"γ = α",B:"γ = 2α",C:"γ = 3α",D:"γ = α/3"},a:"C",e:"For isotropic solids: γ = 3α (volume expansion = 3 × linear expansion). Similarly, β (area) = 2α.",ch:"Thermal Properties of Matter",sub:"Physics",d:"easy"},
{id:"pm5",y:2019,q:"A bimetallic strip bends on heating because:",o:{A:"Both metals expand equally",B:"The two metals have different coefficients of thermal expansion",C:"One metal melts",D:"Thermal conductivity differs"},a:"B",e:"Bimetallic strip: two metals bonded together with different α values. On heating, one expands more → strip bends toward the less-expanding metal.",ch:"Thermal Properties of Matter",sub:"Physics",d:"easy"},
{id:"pm6",y:2022,q:"The wavelength of sound in a medium depends on:",o:{A:"Frequency only",B:"Speed only",C:"Both frequency and speed",D:"Amplitude only"},a:"C",e:"v = fλ → λ = v/f. Wavelength depends on both the speed of sound in the medium and the frequency.",ch:"Waves",sub:"Physics",d:"easy"},
{id:"pm7",y:2020,q:"The phenomenon of beats is produced by:",o:{A:"Two waves with same frequency",B:"Two waves with slightly different frequencies",C:"Reflection of sound",D:"Diffraction of sound"},a:"B",e:"Beats: superposition of two waves with slightly different frequencies → periodic variation in intensity. Beat frequency = |f₁ - f₂|.",ch:"Waves",sub:"Physics",d:"easy"},
{id:"pm8",y:2017,q:"A bar magnet is cut into two equal halves perpendicular to its length. What happens?",o:{A:"Poles are separated",B:"Magnetic moment is halved",C:"Each piece has no poles",D:"Magnetic moment becomes zero"},a:"B",e:"Each half retains both poles (N and S). Length halves → magnetic moment M = m×l halves. Pole strength unchanged.",ch:"Magnetism & Matter",sub:"Physics",d:"medium"},
{id:"pm9",y:2023,q:"The magnetic susceptibility of a diamagnetic material is:",o:{A:"Large and positive",B:"Small and positive",C:"Small and negative",D:"Zero"},a:"C",e:"Diamagnetic: weakly repelled by magnetic field → susceptibility is small and negative (χ < 0).",ch:"Magnetism & Matter",sub:"Physics",d:"medium"},
{id:"bm1",y:2016,q:"Which of the following is NOT a characteristic of living organisms?",o:{A:"Growth",B:"Reproduction",C:"Consciousness",D:"Metabolism"},a:"C",e:"Consciousness is debated — not universally accepted as a defining characteristic. Growth, reproduction, metabolism are universal characteristics of life.",ch:"The Living World",sub:"Biology",d:"easy"},
{id:"bm2",y:2019,q:"Taxonomy is the branch of biology concerned with:",o:{A:"Study of cell structure",B:"Classification and nomenclature of organisms",C:"Study of fossils",D:"Study of heredity"},a:"B",e:"Taxonomy = science of classification, identification, and nomenclature of organisms (Linnaeus is father of taxonomy).",ch:"The Living World",sub:"Biology",d:"easy"},
{id:"bm3",y:2022,q:"Binomial nomenclature was introduced by:",o:{A:"Robert Hooke",B:"Charles Darwin",C:"Carolus Linnaeus",D:"Ernst Haeckel"},a:"C",e:"Carolus Linnaeus introduced binomial nomenclature in 'Species Plantarum' (1753) and 'Systema Naturae' (1758).",ch:"The Living World",sub:"Biology",d:"easy"},
{id:"bm4",y:2014,q:"Five kingdom classification was proposed by:",o:{A:"Linnaeus",B:"Whittaker",C:"Haeckel",D:"Copeland"},a:"B",e:"R.H. Whittaker (1969) proposed five kingdoms: Monera, Protista, Fungi, Plantae, Animalia.",ch:"Biological Classification",sub:"Biology",d:"easy"},
{id:"bm5",y:2017,q:"Mycoplasma is placed in kingdom Monera because it:",o:{A:"Has no cell wall",B:"Is prokaryotic",C:"Is smallest living organism",D:"Causes disease"},a:"B",e:"Monera = prokaryotes. Mycoplasma is prokaryotic (no membrane-bound nucleus). It also lacks cell wall (pleomorphic).",ch:"Biological Classification",sub:"Biology",d:"medium"},
{id:"bm6",y:2020,q:"Viruses are NOT included in any kingdom because they:",o:{A:"Are too small",B:"Are non-cellular and acellular",C:"Cannot reproduce",D:"Have no protein"},a:"B",e:"Viruses are acellular (non-cellular entities). They lack cellular organisation, metabolism outside host → not placed in any kingdom.",ch:"Biological Classification",sub:"Biology",d:"medium"},
{id:"bm7",y:2015,q:"Alternation of generations refers to:",o:{A:"Change of seasons",B:"Alternation between diploid sporophyte and haploid gametophyte",C:"Alternation between asexual and sexual reproduction",D:"Change in plant body form"},a:"B",e:"In plants: diploid sporophyte (2n) → meiosis → haploid gametophyte (n) → fertilisation → sporophyte. This is alternation of generations.",ch:"Plant Kingdom",sub:"Biology",d:"medium"},
{id:"bm8",y:2018,q:"Which group of plants is called 'amphibians of the plant kingdom'?",o:{A:"Algae",B:"Mosses (Bryophytes)",C:"Ferns",D:"Gymnosperms"},a:"B",e:"Bryophytes (mosses, liverworts) need water for reproduction (flagellated sperms) but live on land → 'amphibians of plant kingdom'.",ch:"Plant Kingdom",sub:"Biology",d:"easy"},
{id:"bm9",y:2021,q:"Seeds are found in:",o:{A:"Algae and Fungi",B:"Bryophytes and Pteridophytes",C:"Gymnosperms and Angiosperms",D:"All plants"},a:"C",e:"Seeds are produced by Spermatophytes — Gymnosperms (naked seeds) and Angiosperms (seeds enclosed in fruit).",ch:"Plant Kingdom",sub:"Biology",d:"easy"},
{id:"bm10",y:2016,q:"The edible part of a mango is:",o:{A:"Pericarp",B:"Mesocarp",C:"Endocarp",D:"Seed"},a:"B",e:"In mango (drupe): epicarp = outer skin, mesocarp = fleshy edible part, endocarp = hard stone around seed.",ch:"Morphology of Flowering Plants",sub:"Biology",d:"hard"},
{id:"bm11",y:2019,q:"Tap root system is characteristic of:",o:{A:"Monocots",B:"Dicots",C:"Both monocots and dicots",D:"Pteridophytes"},a:"B",e:"Dicots: tap root (primary root with secondary roots). Monocots: fibrous root system (adventitious roots from base of stem).",ch:"Morphology of Flowering Plants",sub:"Biology",d:"easy"},
{id:"bm12",y:2022,q:"Sunflower is an example of:",o:{A:"Simple fruit",B:"Aggregate fruit",C:"Multiple fruit",D:"Pseudocarp"},a:"C",e:"Sunflower head = multiple fruit — develops from entire inflorescence, not a single flower. Like pineapple and mulberry.",ch:"Morphology of Flowering Plants",sub:"Biology",d:"medium"},
{id:"bm13",y:2015,q:"Vascular bundles in dicot stem are:",o:{A:"Scattered",B:"Arranged in a ring",C:"In two rings",D:"Absent"},a:"B",e:"Dicot stem: vascular bundles arranged in a ring (with cambium → open VBs). Monocot stem: scattered (closed VBs).",ch:"Anatomy of Flowering Plants",sub:"Biology",d:"easy"},
{id:"bm14",y:2018,q:"Casparian strips are found in:",o:{A:"Cortex",B:"Endodermis",C:"Pericycle",D:"Epidermis"},a:"B",e:"Casparian strips: suberin-impregnated bands in walls of endodermis cells. Regulate water and mineral movement into xylem.",ch:"Anatomy of Flowering Plants",sub:"Biology",d:"medium"},
{id:"bm15",y:2021,q:"In plants, water is conducted through:",o:{A:"Sieve tubes",B:"Companion cells",C:"Tracheids and vessels",D:"Parenchyma"},a:"C",e:"Water and minerals conducted upward through xylem — tracheids and vessels (dead cells forming hollow tubes).",ch:"Anatomy of Flowering Plants",sub:"Biology",d:"easy"},
{id:"bm16",y:2014,q:"A cell is placed in a hypotonic solution. It will:",o:{A:"Shrink (plasmolyse)",B:"Swell and possibly burst",C:"Remain unchanged",D:"Lose water"},a:"B",e:"Hypotonic solution: lower solute concentration than cell. Water enters by osmosis → cell swells. Animal cells may burst; plant cells become turgid.",ch:"Cell: Unit of Life",sub:"Biology",d:"easy"},
{id:"bm17",y:2017,q:"Which cell organelle is known as the 'powerhouse of the cell'?",o:{A:"Ribosome",B:"Nucleus",C:"Mitochondria",D:"Golgi apparatus"},a:"C",e:"Mitochondria: site of oxidative phosphorylation (Krebs cycle + ETC) → produces most ATP → 'powerhouse of cell'.",ch:"Cell: Unit of Life",sub:"Biology",d:"easy"},
{id:"bm18",y:2020,q:"Fluid mosaic model of plasma membrane was proposed by:",o:{A:"Robert Hooke",B:"Singer and Nicolson",C:"Davson and Danielli",D:"Schleiden and Schwann"},a:"B",e:"Singer and Nicolson (1972) proposed the fluid mosaic model — phospholipid bilayer with proteins floating in it like 'mosaic'.",ch:"Cell: Unit of Life",sub:"Biology",d:"medium"},
{id:"bm19",y:2016,q:"Double fertilisation is a characteristic feature of:",o:{A:"Gymnosperms",B:"Angiosperms",C:"Bryophytes",D:"Pteridophytes"},a:"B",e:"Double fertilisation (unique to angiosperms): one sperm + egg = zygote (2n); another sperm + two polar nuclei = endosperm (3n).",ch:"Sexual Reproduction in Plants",sub:"Biology",d:"hard"},
{id:"bm20",y:2019,q:"Self-incompatibility in plants prevents:",o:{A:"Cross-pollination",B:"Self-pollination leading to self-fertilisation",C:"Seed formation",D:"Fruit development"},a:"B",e:"Self-incompatibility: genetic mechanism that prevents self-pollen from fertilising eggs of the same plant → promotes outbreeding.",ch:"Sexual Reproduction in Plants",sub:"Biology",d:"medium"},
{id:"bm21",y:2022,q:"Triple fusion in angiosperms produces:",o:{A:"Zygote",B:"Endosperm nucleus",C:"Embryo",D:"Seed coat"},a:"B",e:"Triple fusion: one male gamete + two polar nuclei = primary endosperm nucleus (3n). This develops into nutritive endosperm.",ch:"Sexual Reproduction in Plants",sub:"Biology",d:"medium"},
{id:"bm22",y:2014,q:"Structural organisation in animals — which type of tissue connects bones to muscles?",o:{A:"Tendons",B:"Ligaments",C:"Cartilage",D:"Areolar tissue"},a:"A",e:"Tendons: connect muscles to bones (made of white fibrous connective tissue). Ligaments connect bone to bone.",ch:"Structural Organisation in Animals",sub:"Biology",d:"easy"},
{id:"bm23",y:2017,q:"Earthworm's excretory organs are:",o:{A:"Flame cells",B:"Malpighian tubules",C:"Nephridia",D:"Green glands"},a:"C",e:"Earthworm excretes through nephridia (metanephridia). Flame cells: Platyhelminthes. Malpighian tubules: insects.",ch:"Structural Organisation in Animals",sub:"Biology",d:"medium"},
{id:"bm24",y:2020,q:"The blood of cockroach is:",o:{A:"Red due to haemoglobin",B:"Colourless (haemolymph)",C:"Blue due to haemocyanin",D:"Green"},a:"B",e:"Cockroach has haemolymph (colourless blood) — no respiratory pigment. O₂ transport is via tracheal system directly.",ch:"Structural Organisation in Animals",sub:"Biology",d:"medium"},
{id:"bm25",y:2015,q:"Digestion of starch begins in:",o:{A:"Stomach",B:"Small intestine",C:"Mouth (buccal cavity)",D:"Large intestine"},a:"C",e:"Salivary amylase (ptyalin) in mouth begins starch digestion → converts starch to maltose. Stomach has no amylase.",ch:"Digestion & Absorption",sub:"Biology",d:"easy"},
{id:"bm26",y:2018,q:"Bile is produced by the liver but stored in:",o:{A:"Pancreas",B:"Duodenum",C:"Gall bladder",D:"Stomach"},a:"C",e:"Liver produces bile → stored in gall bladder → released into duodenum via bile duct. Bile emulsifies fats.",ch:"Digestion & Absorption",sub:"Biology",d:"easy"},
{id:"bm27",y:2021,q:"Which enzyme converts trypsinogen to trypsin?",o:{A:"Pepsin",B:"Enterokinase",C:"Chymotrypsin",D:"Amylase"},a:"B",e:"Enterokinase (enteropeptidase) secreted by duodenal epithelium converts inactive trypsinogen → active trypsin.",ch:"Digestion & Absorption",sub:"Biology",d:"medium"},
{id:"bm28",y:2016,q:"The partial pressure of oxygen in alveolar air is approximately:",o:{A:"40 mm Hg",B:"100 mm Hg",C:"159 mm Hg",D:"21 mm Hg"},a:"B",e:"Alveolar air: pO₂ ≈ 100 mm Hg. Atmospheric pO₂ ≈ 159 mm Hg (21% of 760 mm Hg). Deoxygenated blood: pO₂ ≈ 40 mm Hg.",ch:"Breathing & Gas Exchange",sub:"Biology",d:"medium"},
{id:"bm29",y:2019,q:"Tidal volume is the volume of air:",o:{A:"Maximum air that can be inhaled",B:"Air remaining after maximum exhalation",C:"Breathed in and out in normal breathing",D:"Maximum air that can be exhaled"},a:"C",e:"Tidal volume (TV) ≈ 500 mL. Volume of air inspired/expired in a normal quiet breath. IRV + TV + ERV = Vital Capacity.",ch:"Breathing & Gas Exchange",sub:"Biology",d:"easy"},
{id:"bm30",y:2022,q:"Surfactant in lungs prevents:",o:{A:"Entry of pathogens",B:"Collapse of alveoli",C:"Infection",D:"Excess oxygen absorption"},a:"B",e:"Surfactant (dipalmitoyl phosphatidylcholine) reduces surface tension of alveolar fluid → prevents alveolar collapse during exhalation.",ch:"Breathing & Gas Exchange",sub:"Biology",d:"medium"},
{id:"bm31",y:2015,q:"Which formed element of blood is involved in clotting?",o:{A:"RBC",B:"WBC",C:"Platelets",D:"Plasma proteins"},a:"C",e:"Platelets (thrombocytes) aggregate at injury site and release clotting factors → trigger coagulation cascade.",ch:"Body Fluids & Circulation",sub:"Biology",d:"easy"},
{id:"bm32",y:2018,q:"Which chamber of the heart pumps oxygenated blood to the body?",o:{A:"Right atrium",B:"Right ventricle",C:"Left atrium",D:"Left ventricle"},a:"D",e:"Left ventricle → aorta → systemic circulation (entire body). Right ventricle → pulmonary artery → lungs.",ch:"Body Fluids & Circulation",sub:"Biology",d:"easy"},
{id:"bm33",y:2021,q:"ABO blood groups are determined by antigens on:",o:{A:"WBCs",B:"Plasma proteins",C:"RBC surface",D:"Platelets"},a:"C",e:"ABO antigens (A, B glycoproteins) are on RBC surface. Corresponding antibodies are in plasma.",ch:"Body Fluids & Circulation",sub:"Biology",d:"medium"},
{id:"bm34",y:2016,q:"The functional unit of kidney is:",o:{A:"Nephron",B:"Glomerulus",C:"Bowman's capsule",D:"Loop of Henle"},a:"A",e:"Nephron is the structural and functional unit of kidney. Each kidney has ~1 million nephrons.",ch:"Excretory Products",sub:"Biology",d:"easy"},
{id:"bm35",y:2019,q:"Ultrafiltration in kidney occurs in:",o:{A:"Loop of Henle",B:"Distal convoluted tubule",C:"Glomerulus (Bowman's capsule)",D:"Collecting duct"},a:"C",e:"Glomerular filtration (ultrafiltration): blood filtered under pressure in glomerulus → Bowman's capsule collects filtrate.",ch:"Excretory Products",sub:"Biology",d:"medium"},
{id:"bm36",y:2022,q:"Urea is produced in the body from:",o:{A:"Excess carbohydrates",B:"Excess fats",C:"Breakdown of amino acids (deamination)",D:"Breakdown of nucleic acids"},a:"C",e:"Deamination of amino acids in liver produces ammonia → converted to urea (urea cycle/ornithine cycle) → excreted by kidneys.",ch:"Excretory Products",sub:"Biology",d:"medium"},
{id:"bm37",y:2015,q:"Smooth muscle is found in:",o:{A:"Heart",B:"Biceps",C:"Walls of internal organs (viscera)",D:"Diaphragm"},a:"C",e:"Smooth (involuntary) muscle: walls of stomach, intestines, blood vessels, uterus. Cardiac muscle: heart. Skeletal: voluntary movement.",ch:"Locomotion & Movement",sub:"Biology",d:"easy"},
{id:"bm38",y:2018,q:"The basic contractile unit of skeletal muscle is:",o:{A:"Myofibril",B:"Sarcomere",C:"Muscle fibre",D:"Z-line"},a:"B",e:"Sarcomere: basic unit of muscle contraction, from Z-line to Z-line. Contains actin (thin filaments) and myosin (thick filaments).",ch:"Locomotion & Movement",sub:"Biology",d:"medium"},
{id:"bm39",y:2021,q:"Ball and socket joint is found between:",o:{A:"Skull and vertebrae",B:"Femur and pelvic girdle",C:"Radius and ulna",D:"Carpals"},a:"B",e:"Ball and socket joint (e.g., hip joint: femur head in acetabulum of pelvis) allows movement in all directions.",ch:"Locomotion & Movement",sub:"Biology",d:"easy"},
{id:"bm40",y:2016,q:"The myelin sheath of neurons is formed by:",o:{A:"Neurons themselves",B:"Schwann cells (PNS) and oligodendrocytes (CNS)",C:"Astrocytes",D:"Microglia"},a:"B",e:"Myelin sheath: formed by Schwann cells (peripheral nervous system) and oligodendrocytes (CNS). Increases nerve impulse speed.",ch:"Neural Control & Coordination",sub:"Biology",d:"medium"},
{id:"bm41",y:2019,q:"The site of integration of sensory and motor information is:",o:{A:"Spinal cord only",B:"Brain only",C:"Both brain and spinal cord (CNS)",D:"Peripheral nervous system"},a:"C",e:"CNS (brain + spinal cord) integrates all sensory input and coordinates motor output. PNS carries signals to/from CNS.",ch:"Neural Control & Coordination",sub:"Biology",d:"easy"},
{id:"bm42",y:2022,q:"Refractory period in nerve fibre is the time during which:",o:{A:"Nerve fires twice as fast",B:"The nerve cannot respond to another stimulus",C:"Repolarisation is maximum",D:"Na⁺ ions rush in"},a:"B",e:"Refractory period: after firing an action potential, the nerve cannot fire again immediately → ensures unidirectional impulse transmission.",ch:"Neural Control & Coordination",sub:"Biology",d:"medium"},
{id:"bm43",y:2015,q:"Reproductive health refers to:",o:{A:"Absence of sexually transmitted diseases only",B:"Total well-being in all aspects of reproduction",C:"Ability to produce children",D:"Regular menstrual cycle"},a:"B",e:"WHO definition: reproductive health = complete physical, emotional, mental and social well-being related to reproductive system.",ch:"Reproductive Health",sub:"Biology",d:"easy"},
{id:"bm44",y:2018,q:"Oral contraceptive pills work mainly by:",o:{A:"Preventing fertilisation by blocking sperm",B:"Inhibiting ovulation by suppressing LH/FSH",C:"Preventing implantation",D:"Killing sperm"},a:"B",e:"Combined oral contraceptives contain synthetic oestrogen + progesterone → suppress FSH/LH → no follicle development → no ovulation.",ch:"Reproductive Health",sub:"Biology",d:"medium"},
{id:"bm45",y:2021,q:"MTP (Medical Termination of Pregnancy) is legally allowed in India up to:",o:{A:"8 weeks",B:"12 weeks (with one doctor's approval)",C:"20 weeks",D:"24 weeks"},a:"B",e:"MTP Act India: up to 12 weeks with 1 doctor's opinion; 12–20 weeks with 2 doctors' opinions. Used to avoid unwanted pregnancies.",ch:"Reproductive Health",sub:"Biology",d:"medium"},
{id:"bm46",y:2014,q:"Antibiotics are produced by:",o:{A:"Viruses",B:"Microorganisms (bacteria and fungi)",C:"Plants",D:"Animals"},a:"B",e:"Antibiotics are metabolites of microorganisms. Penicillin from Penicillium notatum (fungus); Streptomycin from Streptomyces griseus (bacteria).",ch:"Microbes in Human Welfare",sub:"Biology",d:"easy"},
{id:"bm47",y:2017,q:"Which microorganism is used in biogas production?",o:{A:"Lactobacillus",B:"Methanobacterium (methanogens)",C:"Saccharomyces",D:"Acetobacter"},a:"B",e:"Methanogens (e.g., Methanobacterium) produce biogas (methane + CO₂) by anaerobic breakdown of organic matter.",ch:"Microbes in Human Welfare",sub:"Biology",d:"easy"},
{id:"bm48",y:2020,q:"Sewage treatment uses microbes in:",o:{A:"Primary treatment",B:"Secondary (biological) treatment",C:"Tertiary treatment",D:"Chlorination"},a:"B",e:"Secondary treatment (biological): microorganisms (aerobic bacteria in activated sludge) decompose organic matter in sewage.",ch:"Microbes in Human Welfare",sub:"Biology",d:"medium"},
];

